def test_median_odd():
    assert median([3, 1, 2]) == 2


def test_median_even():
    assert median([1, 2, 3, 4]) == 2.5


def test_median_single():
    assert median([7]) == 7


def test_median_empty_raises():
    try:
        median([])
    except ValueError:
        return
    raise AssertionError('expected ValueError')
